package com.mst.repositories;
import com.mst.models.UserAccount;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class SaleGdnDirectRepository extends SaleGdnPurchaseReturnRepository{
 public static final int DOCUMENT_TYPE_ID=124; public SaleGdnDirectRepository(JdbcTemplate j){super(j);}@Override protected int documentTypeId(){return DOCUMENT_TYPE_ID;}@Override protected String screenName(){return "frmGdnDirect";}@Override protected String recordLabel(){return "GDN Direct";}
 @Override public Map<String,Object> initial(UserAccount u,int y){Map<String,Object>m=new LinkedHashMap<>();var no=q("EXEC dbo.Sp_InvGdn_GetAllMethod @OrganizationId=?,@CompanyId=?,@DocumentTypeId=?,@FinancialYearId=?,@BranchesId=?,@Activity='GenerateInvGdnCode'",u.getOrganizationId(),u.getCompanyId(),DOCUMENT_TYPE_ID,y,u.getBranchesId());m.put("nextNo",no.isEmpty()?1:no.get(0).get("DocNo"));m.put("customers",q("EXEC dbo.Sp_SupplierCustomer_GetAllMethod @OrganizationId=?,@CompanyId=?,@Activity='ReadByOrganizationIdCompanyIdForBinding'",u.getOrganizationId(),u.getCompanyId()));m.put("items",items(u,0));m.put("brands",q("EXEC dbo.USP_Brand_GetAllMethod @OrganizationId=?,@CompanyId=?,@Activity='FormHistory',@Id=0",u.getOrganizationId(),u.getCompanyId()));m.put("warehouses",q("EXEC dbo.USP_GetWarehousesAllocatedToBranch @OrganizationId=?,@CompanyId=?,@BranchId=?",u.getOrganizationId(),u.getCompanyId(),u.getBranchesId()));m.put("crops",q("EXEC dbo.Sp_InvCropYear_GetAllMethod @OrganizationId=?,@CompanyId=?,@Activity='ReadAll'",u.getOrganizationId(),u.getCompanyId()));m.put("jobLots",q("EXEC dbo.USP_GetJobLotsAllocatedToBranch @OrganizationId=?,@CompanyId=?,@BranchId=?",u.getOrganizationId(),u.getCompanyId(),u.getBranchesId()));m.put("packingTypes",q("EXEC dbo.Sp_InvPackingType_GetAllMethod @Activity='ReadAll'"));m.put("cities",q("EXEC dbo.SP_City_GetAllMethod @OrganizationId=?,@CompanyId=?,@MethodType='GetAll'",u.getOrganizationId(),u.getCompanyId()));m.put("transporters",q("EXEC dbo.USP_Accounts_GetAccountTitleByAccountTypeIds @OrganizationId=?,@CompanyId=?,@AppId=?,@UserId=?,@AccountTypeIds=?",u.getOrganizationId(),u.getCompanyId(),u.getAppId(),u.getId(),"6,8"));return m;}
 @Override public List<Map<String,Object>> items(UserAccount u,int ignored){return q("EXEC dbo.USP_Item_AllItemsWithModal @OrganizationId=?,@CompanyId=?",u.getOrganizationId(),u.getCompanyId()).stream().filter(r->number(r.get("ItemTypeOfTypeId"))!=14&&number(r.get("ItemTypeOfTypeId"))!=17).toList();}
}
